"""Durable command idempotency helpers for the HTTP Command API.

Single source of truth for command status transitions. Worker and CommandService
must use these helpers — never raw SQL on ``fsm_command_idempotency``.

Contract (see TASK-CORE-001):

* ``instanceId`` is a BIGINT generated by ``server_fsm_instances.id`` and is
  unique inside ``fsm_command_idempotency`` (enforced by
  ``uq_fsm_command_idempotency_instance``).
* Allowed status values: ``PENDING``, ``PROCESSING``, ``COMPLETED``, ``FAILED``.
* ``COMPLETED`` and ``FAILED`` are terminal: once reached, the status of that
  ``instance_id`` cannot change any more. Immutability is guaranteed on two
  levels (matching the README contract):

  1. **Python state-machine check** — :func:`is_allowed_transition` checks the
     transition graph at runtime. Terminal states have no outgoing edges, so
     any transition out of ``COMPLETED``/``FAILED`` is rejected. The helper
     returns ``False`` (soft no-op) rather than raising, so the worker's
     failure path can treat a concurrent terminal transition as a non-fatal
     race.
  2. **SQL conditional UPDATE** — the ``WHERE status NOT IN ('COMPLETED',
     'FAILED')`` clause is the race-safe guard: if another transaction moved
     the row to a terminal state between the Python check and the UPDATE,
     ``rowcount`` will be 0 and the helper returns ``False``.

* ``errorCode`` is stored inside ``response_json`` (top-level ``errorCode``
  field) so that no schema change is required. ``get_command_status`` lifts it
  onto the top-level response for the public API.
"""

from __future__ import annotations

from typing import Any, Dict, Optional

from sqlalchemy import text
from sqlalchemy.orm import Session

from .serialization import json_dumps, json_loads_object
from .error_codes import normalize_known_code


# Public status vocabulary. Adding a new status requires updating this set,
# the README, and the terminal-state guard.
PENDING = "PENDING"
PROCESSING = "PROCESSING"
COMPLETED = "COMPLETED"
FAILED = "FAILED"

ALLOWED_STATUSES = frozenset({PENDING, PROCESSING, COMPLETED, FAILED})
TERMINAL_STATUSES = frozenset({COMPLETED, FAILED})

# Normative status transition graph (TASK-CORE-001 §3 + §16):
#
#     PENDING  ──►  PROCESSING  ──►  COMPLETED
#                       │
#                       └──────►  FAILED
#
# Terminal states (COMPLETED, FAILED) are immutable: there are no outgoing
# edges. ``PENDING`` and ``PROCESSING`` are non-terminal and can be reached
# from themselves (recovery / idempotent retry) and from each other.
#
# ``PENDING → COMPLETED`` and ``PENDING → FAILED`` are allowed for the
# operational case where a command is accepted and the worker immediately
# resolves it without ever passing through ``PROCESSING`` in the
# idempotency table (e.g. synchronous validation failure inside the worker
# before the ``PROCESSING`` update commits). Forbidding those edges would
# require every worker code path to perform two writes, which is brittle.
ALLOWED_TRANSITIONS = frozenset(
    {
        # From PENDING: worker may start (PROCESSING) or resolve immediately.
        (PENDING, PROCESSING),
        (PENDING, COMPLETED),
        (PENDING, FAILED),
        # From PROCESSING: worker finishes (terminal) or restarts.
        (PROCESSING, COMPLETED),
        (PROCESSING, FAILED),
        (PROCESSING, PENDING),  # recovery: retry after crash
        # Terminal states are immutable — no outgoing edges. The empty set
        # below documents this explicitly; the conditional UPDATE in
        # ``update_command_status`` is the runtime guard.
    }
)


class CommandStatusError(ValueError):
    """Raised when a caller tries to set an invalid status, attempts an
    unsupported transition, or transitions out of a terminal status."""


def is_allowed_transition(from_status: Optional[str], to_status: str) -> bool:
    """Return ``True`` when ``from_status → to_status`` is permitted by the
    normative state machine.

    ``from_status=None`` represents "the row does not exist yet" (the initial
    write performed by :func:`put_command_idempotency`). Only ``PENDING`` is
    a valid initial status — a fresh command execution must start in
    ``PENDING`` and progress through ``PROCESSING`` to a terminal state.
    Permitting ``None → COMPLETED`` or ``None → FAILED`` would let a caller
    fabricate a terminal result without ever invoking the worker, bypassing
    the entire lifecycle.

    For existing rows:

    * idempotent re-write (same status → same status) is allowed;
    * terminal states (``COMPLETED``/``FAILED``) have no outgoing edges;
    * all other transitions must be in ``ALLOWED_TRANSITIONS``.
    """

    if to_status not in ALLOWED_STATUSES:
        return False
    if from_status is None:
        # Initial write — only PENDING is permitted.
        return to_status == PENDING
    if from_status == to_status:
        # Idempotent re-write of the same status (e.g. recovery flips a
        # PROCESSING row back to PENDING; worker marks PROCESSING twice).
        return True
    if from_status in TERMINAL_STATUSES:
        # Terminal immutability: no outgoing edges.
        return False
    return (from_status, to_status) in ALLOWED_TRANSITIONS


def _normalize_response(response: Optional[Dict[str, Any]]) -> Dict[str, Any]:
    if not isinstance(response, dict):
        return {}
    return dict(response)


def get_command_idempotency(
    session: Session,
    *,
    service: str,
    key: str,
    scope: str = "command",
    include_status: bool = False,
) -> Optional[Dict[str, Any]]:
    """Lookup an idempotency record by ``(service, scope, idempotency_key)``.

    Filters by ``expires_at`` — expired records are invisible to callers.
    Use :func:`get_command_idempotency_unfiltered` to detect expired records
    (e.g. to return 404 for a duplicate POST instead of silently creating a
    new execution).
    """

    row = session.execute(
        text(
            """
            SELECT instance_id, response_json, status
            FROM fsm_command_idempotency
            WHERE service = :service
              AND scope = :scope
              AND idempotency_key = :key
              AND (expires_at IS NULL OR expires_at > UTC_TIMESTAMP())
            """
        ),
        {"service": service, "scope": scope, "key": key},
    ).fetchone()
    if row is None:
        return None
    result: Dict[str, Any] = {
        "instance_id": int(row[0]) if row[0] is not None else None,
        "response": _normalize_response(json_loads_object(row[1])),
    }
    if include_status and row[2] is not None:
        result["status"] = str(row[2])
    return result


def get_command_idempotency_unfiltered(
    session: Session,
    *,
    service: str,
    key: str,
    scope: str = "command",
    include_status: bool = False,
) -> Optional[Dict[str, Any]]:
    """Lookup an idempotency record **without** the ``expires_at`` filter.

    Used by :func:`CommandService.accept` to distinguish "no record exists"
    from "record exists but has expired". When this returns a row but
    :func:`get_command_idempotency` returns None, the record has expired and
    a duplicate POST must be treated as 404 (not silently create a new
    execution with the same Idempotency-Key).

    The ``include_status`` parameter mirrors :func:`get_command_idempotency`
    for API consistency. When ``True``, the returned dict includes the
    ``status`` key; when ``False`` (default), it is omitted — matching the
    shape of :func:`get_command_idempotency`.
    """

    row = session.execute(
        text(
            """
            SELECT instance_id, response_json, status
            FROM fsm_command_idempotency
            WHERE service = :service
              AND scope = :scope
              AND idempotency_key = :key
            """
        ),
        {"service": service, "scope": scope, "key": key},
    ).fetchone()
    if row is None:
        return None
    result: Dict[str, Any] = {
        "instance_id": int(row[0]) if row[0] is not None else None,
        "response": _normalize_response(json_loads_object(row[1])),
    }
    if include_status and row[2] is not None:
        result["status"] = str(row[2])
    return result


def get_command_by_instance_id(
    session: Session,
    instance_id: int,
) -> Optional[Dict[str, Any]]:
    """Lookup an idempotency record by ``instance_id``.

    Used by the Command Completion API (``GET /api/commands/{instanceId}``).

    Filters by ``expires_at`` so that records past their retention period are
    treated as if they no longer exist — the GET endpoint then returns 404.
    This matches the public contract documented in README and the
    TASK-CORE-001 §10 requirement: "Запрос статуса после истечения retention
    возвращает 404."
    """

    row = session.execute(
        text(
            """
            SELECT instance_id, response_json, status, service, idempotency_key
            FROM fsm_command_idempotency
            WHERE instance_id = :instance_id
              AND (expires_at IS NULL OR expires_at > UTC_TIMESTAMP())
            """
        ),
        {"instance_id": instance_id},
    ).fetchone()
    if row is None:
        return None
    response = _normalize_response(json_loads_object(row[1]))
    return {
        "instance_id": int(row[0]) if row[0] is not None else None,
        "response": response,
        "status": str(row[2]) if row[2] is not None else None,
        "service": str(row[3]) if row[3] is not None else None,
        "idempotency_key": str(row[4]) if row[4] is not None else None,
    }


def _get_current_status(session: Session, instance_id: int) -> Optional[str]:
    """Return the current status of a command execution, or ``None`` if the
    row does not exist. Used by ``update_command_status`` for runtime
    state-machine enforcement.

    Does **not** filter by ``expires_at`` — this is intentional. The worker
    must be able to advance the status of an expired execution (e.g. mark
    it ``FAILED`` after a crash, or ``COMPLETED`` after a delayed success),
    even though the GET endpoint will not return that status to the client.
    This keeps the internal execution state consistent with
    ``server_fsm_instances`` regardless of retention expiry. The public
    contract (expired → 404) is enforced only at the read path
    (``get_command_by_instance_id`` / ``get_command_idempotency``), not at
    the write path.
    """

    row = session.execute(
        text(
            """
            SELECT status FROM fsm_command_idempotency
            WHERE instance_id = :instance_id
            """
        ),
        {"instance_id": instance_id},
    ).fetchone()
    if row is None:
        return None
    return str(row[0]) if row[0] is not None else None


def update_command_status(
    session: Session,
    instance_id: int,
    status: str,
    *,
    error_code: Optional[str] = None,
    error_message: Optional[str] = None,
) -> bool:
    """Transition the status of a command execution.

    Enforcement steps (in order):

    1. **Status vocabulary** — ``status`` must be in ``ALLOWED_STATUSES``;
       otherwise ``CommandStatusError`` is raised. This is a sanity check
       independent of the state machine.
    2. **Runtime state-machine** — reads the current status and calls
       :func:`is_allowed_transition`. If the transition is not in
       ``ALLOWED_TRANSITIONS`` (and is not an idempotent re-write of the
       same status), ``CommandStatusError`` is raised. This makes
       ``ALLOWED_TRANSITIONS`` real runtime enforcement, not just
       declarative documentation. Terminal states return ``False`` (soft
       no-op) so the worker's failure path can treat a concurrent
       terminal transition as a non-fatal race rather than an exception.
    3. **Conditional UPDATE** — the SQL ``WHERE status NOT IN
       ('COMPLETED', 'FAILED')`` clause is the race-safe guard (the second
       immutability layer described in the README): if another transaction
       moved the row to a terminal state between our
       ``_get_current_status`` check and our UPDATE, ``rowcount`` will be 0
       and we return ``False``. This prevents the FAILED-branch from lying
       to the caller (a defect in the third review).

    On ``FAILED`` the ``errorCode`` and ``errorMessage`` fields are merged
    into ``response_json`` so the public GET endpoint can lift them onto the
    top-level response. The return value is driven by ``rowcount`` so a race
    loser (whose conditional UPDATE matched 0 rows) gets ``False`` rather
    than a misleading ``True``.

    Returns ``True`` when the row was updated, ``False`` when the row was
    already terminal, no row matched ``instance_id``, or the conditional
    UPDATE matched 0 rows due to a concurrent transition.

    Note on idempotent re-writes: when ``current_status == status`` (e.g.
    PENDING → PENDING), the helper returns ``True`` if the conditional UPDATE
    matched 1 row, ``False`` otherwise. This means "the row is in the
    requested status" — which is useful for the worker's failure path (it
    knows the row reached the desired state) and for recovery (it knows the
    row is already PENDING). The alternative — returning ``False`` because
    "nothing changed" — would make the caller think the transition failed,
    which is incorrect for an idempotent operation.
    """

    if status not in ALLOWED_STATUSES:
        raise CommandStatusError(
            f"Invalid command status: {status!r}; allowed: "
            f"{sorted(ALLOWED_STATUSES)}"
        )

    current_status = _get_current_status(session, instance_id)
    if current_status is None:
        # Row does not exist. Nothing to update.
        return False

    # Runtime state-machine enforcement. Idempotent re-writes (same status)
    # are allowed; terminal states return False (soft no-op); everything
    # else must be in ALLOWED_TRANSITIONS.
    if not is_allowed_transition(current_status, status):
        if current_status in TERMINAL_STATUSES:
            # Terminal immutability — return False rather than raise, so the
            # worker's failure path (which calls update_command_status with
            # FAILED after a concurrent COMPLETED) can treat this as a soft
            # no-op instead of an exception.
            return False
        raise CommandStatusError(
            f"Invalid status transition: {current_status!r} → {status!r}; "
            f"allowed transitions are defined in ALLOWED_TRANSITIONS"
        )

    if status == FAILED and error_code:
        # Persist errorCode inside response_json so the schema does not need
        # to change. GET will lift it onto the top-level response.
        #
        # Race-safety: both the SELECT and the UPDATE carry the
        # ``status NOT IN ('COMPLETED', 'FAILED')`` guard. If another worker
        # already moved the row to a terminal state between our two queries,
        # the SELECT returns None (we return False) or the UPDATE matches 0
        # rows (we return False based on rowcount). Returning ``True``
        # unconditionally here was a BLOCKER in the third review — it caused
        # server_fsm_instances and fsm_command_idempotency to diverge.
        #
        # errorCode vocabulary enforcement: the caller may pass any string,
        # but only codes in ``KNOWN_ERROR_CODES`` (defined in
        # ``error_codes.py``) are part of the public API contract. An
        # unknown code is normalised to ``INTERNAL_ERROR`` so the public
        # response never contains an undocumented value. This is enforced
        # here (write path) rather than only in ``get_command_status`` (read
        # path) so the stored data is clean even if a future caller bypasses
        # ``classify_exception``.
        #
        # Note on response_json mutation: the SELECT-then-UPDATE pattern reads
        # response_json, merges errorCode/errorMessage, and writes it back. If
        # another transaction modified response_json between the SELECT and
        # the UPDATE, that change would be overwritten. In practice this is
        # safe because response_json is effectively immutable after POST —
        # only this FAILED branch mutates it, and the conditional UPDATE
        # serialises concurrent FAILED attempts (only the first one matches).
        # If response_json ever becomes mutable from other code paths, this
        # pattern must be revisited (e.g. switch to JSON_MERGE_PATCH in SQL).
        normalised_code = normalize_known_code(error_code)
        row = session.execute(
            text(
                """
                SELECT response_json FROM fsm_command_idempotency
                WHERE instance_id = :instance_id
                  AND status NOT IN ('COMPLETED', 'FAILED')
                """
            ),
            {"instance_id": instance_id},
        ).fetchone()
        if row is None:
            return False
        response = _normalize_response(json_loads_object(row[0]))
        response["errorCode"] = normalised_code
        if error_message is not None:
            response["errorMessage"] = error_message
        response["status"] = FAILED
        result = session.execute(
            text(
                """
                UPDATE fsm_command_idempotency
                SET status = :status, response_json = :response_json
                WHERE instance_id = :instance_id
                  AND status NOT IN ('COMPLETED', 'FAILED')
                """
            ),
            {
                "instance_id": instance_id,
                "status": status,
                "response_json": json_dumps(response),
            },
        )
        return int(result.rowcount or 0) > 0

    result = session.execute(
        text(
            """
            UPDATE fsm_command_idempotency
            SET status = :status
            WHERE instance_id = :instance_id
              AND status NOT IN ('COMPLETED', 'FAILED')
            """
        ),
        {"instance_id": instance_id, "status": status},
    )
    return int(result.rowcount or 0) > 0


def put_command_idempotency(
    session: Session,
    *,
    service: str,
    key: str,
    response: Dict[str, Any],
    instance_id: Optional[int] = None,
    scope: str = "command",
    ttl_hours: int = 24,
    status: Optional[str] = None,
) -> bool:
    """Insert an idempotency record (the initial write).

    The initial status is normally ``PENDING`` — the command has been accepted
    but the worker has not started processing yet. ``status=None`` defaults to
    ``PENDING``.

    The runtime state machine (:func:`is_allowed_transition`) is invoked with
    ``from_status=None`` to validate the initial write. Only ``PENDING`` is
    semantically correct for a fresh record; passing any other status raises
    :class:`CommandStatusError`. This prevents callers from creating a row
    that starts in a terminal state, which would bypass the normative
    ``PENDING → PROCESSING → COMPLETED/FAILED`` lifecycle.

    Returns ``True`` when the row was inserted, ``False`` when the key already
    existed (caller should treat this as a duplicate and re-read the existing
    record).
    """

    final_status = status or PENDING
    if final_status not in ALLOWED_STATUSES:
        raise CommandStatusError(
            f"Invalid command status: {final_status!r}; allowed: "
            f"{sorted(ALLOWED_STATUSES)}"
        )
    # Runtime state-machine enforcement for the initial write. ``None`` as
    # ``from_status`` represents "row does not exist yet" — but we still
    # restrict the allowed initial statuses. Only ``PENDING`` makes sense for
    # a freshly inserted command; anything else would skip the normative
    # lifecycle (e.g. inserting directly as ``COMPLETED`` would let a caller
    # bypass the worker entirely and fabricate a success result).
    if not is_allowed_transition(None, final_status):
        raise CommandStatusError(
            f"Invalid initial status: {final_status!r}; a new command "
            f"execution must start in {PENDING!r}"
        )
    response_with_status = _normalize_response(response)
    response_with_status.setdefault("status", final_status)

    result = session.execute(
        text(
            """
            INSERT IGNORE INTO fsm_command_idempotency
                (service, scope, idempotency_key, instance_id, response_json, status,
                 created_at, expires_at)
            VALUES
                (:service, :scope, :key, :instance_id, :response_json, :status,
                 UTC_TIMESTAMP(),
                 DATE_ADD(UTC_TIMESTAMP(), INTERVAL :ttl HOUR))
            """
        ),
        {
            "service": service,
            "scope": scope,
            "key": key,
            "instance_id": instance_id,
            "response_json": json_dumps(response_with_status),
            "ttl": ttl_hours,
            "status": final_status,
        },
    )
    return int(getattr(result, "rowcount", 0) or 0) > 0
